'use strict';
// REGREV #16 focused WR-quality lab. DEV selects; final 25% HOLD untouched.
const fs=require('fs'),R=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=R.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
function ema(p){let E=[],e=M[0].c,k=2/(p+1);for(let i=0;i<N;i++){e=M[i].c*k+e*(1-k);E[i]=e}return E}function atr(p=14){let A=Array(N).fill(NaN);for(let i=p;i<N;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));A[i]=s/p}return A}const A=atr(),E20=ema(20),E50=ema(50);function avg(i,n=50){let s=0,c=0;for(let j=i-n;j<i;j++)if(Number.isFinite(A[j])){s+=A[j];c++}return c?s/c:NaN}const hr=i=>new Date(M[i].t).getUTCHours();
function signal(i,q){let av=avg(i);if(!(A[i]/av>=q.ar))return;let b=M[i],rg=b.h-b.l;if(!(rg>0))return;let bull=b.c>b.o,bear=b.c<b.o,body=Math.abs(b.c-b.o)/rg,up=(b.h-Math.max(b.o,b.c))/rg,dn=(Math.min(b.o,b.c)-b.l)/rg,cpB=(b.c-b.l)/rg,cpS=(b.h-b.c)/rg;if(body<q.body||q.block.includes(hr(i)))return;let slope=(E20[i]-E20[i-6])/A[i],sep=Math.abs(E20[i]-E50[i])/A[i];if(sep<q.sep)return;if(q.slope>0&&Math.abs(slope)>q.slope)return;if(q.side!=='SELL'&&(E20[i]-b.c)/A[i]>=q.dist&&bull&&cpB>=q.cp&&dn>=q.wick)return'BUY';if(q.side!=='BUY'&&(b.c-E20[i])/A[i]>=q.dist&&bear&&cpS>=q.cp&&up>=q.wick)return'SELL'}
function run(q,lo,hi){let T=[],o=null;for(let i=Math.max(100,lo);i<Math.min(N-1,hi);i++){if(o){let b=M[i],px=null;if(o.s==='BUY'){if(b.l<=o.sl)px=o.sl;else if(b.h>=o.tp)px=o.tp}else{if(b.h>=o.sl)px=o.sl;else if(b.l<=o.tp)px=o.tp}if(px==null&&i-o.ei+1>=8)px=b.c;if(px!=null){T.push({...o,r:o.s==='BUY'?(px-o.en)/(o.en-o.sl):(o.en-px)/(o.sl-o.en)});o=null}continue}let s=signal(i,q);if(!s)continue;let en=M[i+1].o,r=A[i];o={s,en,sl:s==='BUY'?en-r:en+r,tp:s==='BUY'?en+1.5*r:en-1.5*r,ei:i+1}}return T}function st(T){let w=0,g=0,l=0,e=0,p=0,dd=0,ls=0,ml=0;for(const x of T){e+=x.r;if(x.r>0){w++;g+=x.r;ls=0}else{l+=-x.r;ls++;ml=Math.max(ml,ls)}p=Math.max(p,e);dd=Math.max(dd,p-e)}return{n:T.length,wr:T.length?100*w/T.length:0,pf:l?g/l:g?99:0,net:e,dd,ls:ml}}
let X=[];for(let side of ['BOTH','BUY','SELL'])for(let ar of [1.2,1.25,1.3,1.4])for(let dist of [1.9,2,2.1,2.2])for(let cp of [.65,.7,.75,.8])for(let body of [0,.25,.4,.55])for(let wick of [0,.08,.15,.25])for(let sep of [0,.1,.2])for(let slope of [0,.15,.3]){let q={side,ar,dist,cp,body,wick,sep,slope,block:[20,21,22,23]},d=st(run(q,0,C));if(d.n<55)continue;let score=d.net+Math.min(d.pf,3)*7-d.dd*.7+(d.wr-50)*.5;X.push({q,d,score})}X.sort((a,b)=>b.score-a.score);
console.log(`REGREV #16 WR QUALITY LAB | M5=${N} DEV=${C} HOLD=${N-C}`);console.log('FIXED EXIT: SL=1ATR TP=1.5ATR HOLD=8 | fixed block UTC20-23');console.log('\n🏆 TOP 40 DEV → UNTOUCHED HOLD');X.slice(0,40).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)} DD${h.dd.toFixed(2)}`)});
console.log('\n🎯 HIGH-WR ROBUST SHORTLIST (DEV WR>=55, T>=70; HOLD shown only after ranking)');X.filter(x=>x.d.wr>=55&&x.d.n>=70).slice(0,25).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net.toFixed(2)}`)});console.log('\nDo not promote on WR alone: require positive DEV/HOLD, PF stability, useful sample, then locked validation.');